fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap() is safe
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap() is safe
    *a.iter().max().unwrap()
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    assert!(!a.is_empty(), "Input array must be non-empty");
    assert!(q >= 0 && q <= 100, "Quantile must be in range [0, 100]");

    // If q == 0, return min directly (satisfies requirement)
    if q == 0 {
        return get_min_val(&a);
    }
    // If q == 100, return max directly (satisfies requirement)
    if q == 100 {
        return get_max_val(&a);
    }

    // Sort the array so that we can select the quantile
    a.sort_unstable();

    // Compute the index corresponding to quantile q.
    // Use: index = floor((q / 100) * (n - 1))
    // This ensures q=0 -> index=0, q=100 -> index=n-1.
    let n = a.len();
    let idx = ((q as usize) * (n - 1)) / 100;

    a[idx]
}